/**
 * Precompiles the shippable application payload with esbuild.
 *
 * Input is the TypeScript source (plus the generated build metadata), output
 * is dist/pack — a minified, self-contained mirror of the final
 * resources/app layout, so package-app.js can copy it verbatim:
 *
 *   dist/pack/src/main/main.js            main process (electron + ogg decoder external)
 *   dist/pack/src/main/preload.bundle.js  sandboxed preload (single file)
 *   dist/pack/src/main/build-info.json    copied from the tsc build (write-build-info.js)
 *   dist/pack/renderer/index.html         copied from src/renderer
 *   dist/pack/renderer/styles.css         copied from src/renderer
 *   dist/pack/renderer/renderer/app.js    renderer ESM bundle
 *
 * The decoder dependency stays external and unpacked: @eshaz/web-worker
 * spawns worker threads from real files on disk, so the node_modules closure
 * must remain a directory (package-app.js copies and prunes it).
 *
 * Source maps are generated with full sourcesContent, split out of the
 * payload into dist/<name>-<version>-maps/ and archived as
 * release/<name>-<version>-maps.tar.xz (+ .sha256). The minified files keep
 * their //# sourceMappingURL comments, so dropping the maps archive open next
 * to the payload makes DevTools symbolicate stacks again. The archive is the
 * analysis input for CI and release drafts; it never ships inside the app.
 */
const fs = require("fs");
const path = require("path");
const { createHash } = require("crypto");
const { execFileSync } = require("child_process");
const esbuild = require("esbuild");
const { buildPreloadBundle } = require("./bundle-preload.js");
const { copyRendererAssets } = require("./copy-renderer-assets.js");

const root = path.join(__dirname, "..");
const pkg = require("../package.json");
const packDir = path.join(root, "dist", "pack");
const mapsName = `${pkg.name}-${pkg.version}-maps`;
const mapsDir = path.join(root, "dist", mapsName);
const releaseRoot = path.join(root, "release");

function fail(message) {
  throw new Error("bundle-app: " + message);
}

// The payload embeds build-info.json generated by write-build-info.js; refuse
// to bundle stale metadata (the same gate package-app.js applies).
const buildInfoPath = path.join(root, "dist", "src", "main", "build-info.json");
if (!fs.existsSync(buildInfoPath)) fail("dist/src/main/build-info.json is missing; run npm run build first");
const buildInfo = JSON.parse(fs.readFileSync(buildInfoPath, "utf8"));
if (buildInfo.version !== pkg.version) fail("build metadata version is stale; rebuild first");

for (const dir of [packDir, mapsDir]) fs.rmSync(dir, { recursive: true, force: true });

const warnings = [];
function build(entry, outfile, options) {
  const result = esbuild.buildSync({
    entryPoints: [entry],
    outfile,
    bundle: true,
    target: "es2022",
    minify: true,
    // linked: external .map plus a //# sourceMappingURL comment, so the maps
    // archive restores debugging when unpacked next to the payload.
    sourcemap: "linked",
    sourcesContent: true,
    logLevel: "warning",
    ...options,
  });
  warnings.push(...result.warnings);
}

// Main process: CommonJS, electron and the decoder stay external. The decoder
// import is dynamic and lazy in core/ogg.ts; esbuild's cjs output keeps that
// laziness through a require-based helper.
build(path.join(root, "src", "main", "main.ts"), path.join(packDir, "src", "main", "main.js"), {
  platform: "node",
  format: "cjs",
  external: ["electron", "@wasm-audio-decoders/ogg-vorbis"],
});

// Sandboxed preload: single self-contained CommonJS file (no runtime require
// except "electron").
buildPreloadBundle(path.join(packDir, "src", "main", "preload.bundle.js"), { minify: true, sourcemap: "linked" });

// Renderer: one ESM bundle; index.html references renderer/app.js next to it.
build(path.join(root, "src", "renderer", "app.ts"), path.join(packDir, "renderer", "renderer", "app.js"), {
  platform: "browser",
  format: "esm",
});

// Static assets and build metadata, at the paths main.js resolves at runtime.
copyRendererAssets(path.join(packDir, "renderer"));
fs.copyFileSync(buildInfoPath, path.join(packDir, "src", "main", "build-info.json"));

// Split the source maps out of the payload, mirroring the directory layout.
const moved = [];
(function moveMaps(dir) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const source = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      moveMaps(source);
      continue;
    }
    if (!entry.name.endsWith(".map")) continue;
    const target = path.join(mapsDir, path.relative(packDir, source));
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.renameSync(source, target);
    moved.push(path.relative(packDir, source));
  }
})(packDir);
if (moved.length === 0) fail("no source maps were generated; check the esbuild sourcemap settings");

// Sanity: the payload must be map-free and the preload must not require
// relative modules at runtime (sandboxed preloads cannot).
for (const found of fs.readdirSync(path.join(packDir, "src", "main"))) {
  if (found.endsWith(".map")) fail("a source map survived in the payload: " + found);
}
const preloadSource = fs.readFileSync(path.join(packDir, "src", "main", "preload.bundle.js"), "utf8");
if (/require\(['"]\.\//.test(preloadSource)) fail("preload bundle still requires a relative module");

// Archive the maps as tar.xz with the system tar (-J applies the xz filter;
// available on Linux, macOS and the Git Bash that ships with Windows). This
// avoids spawning the 7zip-bin binary, whose executable bit is not preserved
// by npm on Linux runners. NB: the archive name stays relative — GNU tar
// reads "A:\..." style absolute names as host:device tape specs, so -C
// carries the paths instead.
fs.mkdirSync(releaseRoot, { recursive: true });
const archive = path.join(releaseRoot, `${mapsName}.tar.xz`);
fs.rmSync(archive, { force: true });
execFileSync("tar", ["-cJf", path.basename(archive), "-C", path.join(root, "dist"), mapsName], { cwd: releaseRoot, stdio: "ignore" });
const digest = createHash("sha256").update(fs.readFileSync(archive)).digest("hex");
fs.writeFileSync(archive + ".sha256", `${digest}  ${path.basename(archive)}\n`);

for (const warning of warnings) console.warn(warning.text);
console.log(`payload: ${path.relative(root, packDir)} (${moved.length} maps split out)`);
console.log(`symbols: ${path.relative(root, archive)}`);
